<?php
require_once __DIR__.'/includes/db.php';require_once __DIR__.'/includes/modulos_clinica.php';$pdo=getDB();asegurarModulosClinica($pdo);$token=trim((string)($_GET['token']??''));$q=$pdo->prepare('SELECT m.id,m.nombre,m.identificador,m.especie,m.raza,m.peso,m.fecha_nacimiento,d.nombre dueno,d.telefono FROM carnets_mascotas c JOIN mascotas m ON m.id=c.mascota_id JOIN duenos d ON d.id=m.dueno_id WHERE c.token=:token');$q->execute([':token'=>$token]);$m=$q->fetch();if(!$m){http_response_code(404);exit('Carnet no encontrado');}$q=$pdo->prepare('SELECT nombre_vacuna,fecha_aplicacion,fecha_proxima_dosis FROM vacunas WHERE mascota_id=:id ORDER BY fecha_aplicacion DESC LIMIT 8');$q->execute([':id'=>(int)$m['id']]);$vacunas=$q->fetchAll();function ce($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$url=((!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http').'://'.$_SERVER['HTTP_HOST'].$_SERVER['REQUEST_URI'];?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Carnet de <?=ce($m['nombre'])?></title><style>body{margin:0;background:#eef5f0;font:16px system-ui;color:#18312a}.wrap{max-width:760px;margin:40px auto;padding:20px}.card{background:#fff;border-radius:22px;box-shadow:0 16px 50px #173b2920;overflow:hidden}.head{background:#28675d;color:#fff;padding:28px;display:flex;justify-content:space-between;align-items:center}.body{padding:28px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.label{font-size:12px;text-transform:uppercase;color:#78918a;font-weight:700}.value{font-weight:700;margin-top:3px}.vac{padding:12px 0;border-bottom:1px solid #edf2f0}.qr{background:#fff;padding:8px;border-radius:10px}@media(max-width:600px){.wrap{margin:0;padding:10px}.grid{grid-template-columns:1fr}.head{align-items:flex-start}}</style></head><body><main class="wrap"><section class="card"><header class="head"><div><small>CARNET VETERINARIO DIGITAL</small><h1><?=ce($m['nombre'])?></h1><div><?=ce($m['identificador'])?> · <?=ce($m['especie'])?> <?=ce($m['raza'])?></div></div><div id="qr" class="qr"></div></header><div class="body"><div class="grid"><div><div class="label">Dueño</div><div class="value"><?=ce($m['dueno'])?></div></div><div><div class="label">Contacto de emergencia</div><div class="value"><a href="tel:<?=ce($m['telefono'])?>"><?=ce($m['telefono'])?></a></div></div><div><div class="label">Peso</div><div class="value"><?=ce($m['peso'])?> kg</div></div><div><div class="label">Nacimiento</div><div class="value"><?=ce($m['fecha_nacimiento']?date('d/m/Y',strtotime($m['fecha_nacimiento'])):'Sin registrar')?></div></div></div><h2>Vacunas</h2><?php if(!$vacunas):?><p>Sin vacunas registradas.</p><?php endif;?><?php foreach($vacunas as $v):?><div class="vac"><strong><?=ce($v['nombre_vacuna'])?></strong><div>Aplicada: <?=ce(date('d/m/Y',strtotime($v['fecha_aplicacion'])))?><?= $v['fecha_proxima_dosis']?' · Próxima: '.ce(date('d/m/Y',strtotime($v['fecha_proxima_dosis']))):''?></div></div><?php endforeach;?></div></section></main><script src="https://cdn.jsdelivr.net/npm/qrcodejs@1.0.0/qrcode.min.js"></script><script>new QRCode(document.getElementById('qr'),{text:<?=json_encode($url)?>,width:88,height:88});</script></body></html>
